DROP TABLE IF EXISTS `t_note`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_note` (
  `id` int NOT NULL AUTO_INCREMENT,
  `content` varchar(255) NOT NULL COMMENT '记事内容',
  `due_date` date NOT NULL COMMENT '截止日期（必填）',
  `due_time` time NOT NULL COMMENT '截止时间（必填，默认设为全天）',
  `status` tinyint NOT NULL DEFAULT '2' COMMENT '状态ID，默认待办',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `notes` text COMMENT '备注信息（可选）',
  PRIMARY KEY (`id`),
  KEY `idx_due_datetime` (`due_date`,`due_time`),
  KEY `idx_status` (`status`),
  CONSTRAINT `t_note_ibfk_1` FOREIGN KEY (`status`) REFERENCES `t_status` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=123 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='待办记事表（强制时间约束）';
/*!40101 SET character_set_client = @saved_cs_client */;

